import{_ as e,C as i,o as t,c as o,E as s,a4 as c}from"./chunks/framework.2-Vke5-n.js";const k=JSON.parse('{"title":"Slack利用ガイドライン","description":"","frontmatter":{"sidebarDepth":4,"title":"Slack利用ガイドライン","author":"フューチャー株式会社","head":[["meta",{"name":"keywords","content":"Slack"}]]},"headers":[],"relativePath":"documents/forSlack/slack_usage_guidelines.md","filePath":"documents/forSlack/slack_usage_guidelines.md"}'),r={name:"documents/forSlack/slack_usage_guidelines.md"};function p(n,a,d,h,u,b){const l=i("page-title");return t(),o("div",null,[s(l),a[0]||(a[0]=c('<p>本ガイドラインはSlackを対象に利用方針についてのベースとなる規約を設け、Slackを用いてより良いコミュニケーションを促進することを目的とする。</p><p>位置づけ・適用範囲・免責事項は <a href="./">Introduction</a> を参照。</p><h2 id="管理者向け推奨設定" tabindex="-1">管理者向け推奨設定 <a class="header-anchor" href="#管理者向け推奨設定" aria-label="Permalink to &quot;管理者向け推奨設定&quot;">​</a></h2><h3 id="workspace-access" tabindex="-1">Workspace Access <a class="header-anchor" href="#workspace-access" aria-label="Permalink to &quot;Workspace Access&quot;">​</a></h3><p>チーム、プロジェクトでの利用の場合は リクエスト制（<code>By Request</code>） もしくは招待制（ <code>Invite Only</code>）の設定を推奨する。</p><h3 id="デフォルトチャンネル" tabindex="-1">デフォルトチャンネル <a class="header-anchor" href="#デフォルトチャンネル" aria-label="Permalink to &quot;デフォルトチャンネル&quot;">​</a></h3><p>ワークスペースにメンバーを追加すると <code>#general</code> へ自動参加する。他にもメンバー全員に参加して欲しいチャンネルがある場合には、デフォルトチャンネルを追加する。</p><div class="tip custom-block"><p class="custom-block-title">ユーザーグループに対してもデフォルトチャンネルを設定できるため、用途に応じて使い分けると良い。</p></div><h3 id="表示名ガイドライン" tabindex="-1">表示名ガイドライン <a class="header-anchor" href="#表示名ガイドライン" aria-label="Permalink to &quot;表示名ガイドライン&quot;">​</a></h3><p>ワークスペースごとにガイドラインを設定することを推奨する。後述の表示名設定や、その他チームコミュニケーションにおけるルールを設定する。設定できる権限を持つのはワークスペースのオーナーだけである点に注意する。</p><h3 id="ワークスペースの管理者" tabindex="-1">ワークスペースの管理者 <a class="header-anchor" href="#ワークスペースの管理者" aria-label="Permalink to &quot;ワークスペースの管理者&quot;">​</a></h3><p>ワークスペース内に複数のチームが混在する場合、それぞれのチームごとに管理者権限保持者を設定すること。</p><p>理由:</p><ul><li>管理者権限を持った人しか実行できないオペレーションがあった際、チーム内で解決できる状態を作っておくことが望ましいため</li></ul><h2 id="ユーザー向け推奨設定" tabindex="-1">ユーザー向け推奨設定 <a class="header-anchor" href="#ユーザー向け推奨設定" aria-label="Permalink to &quot;ユーザー向け推奨設定&quot;">​</a></h2><h3 id="アカウントアイコンを設定する" tabindex="-1">アカウントアイコンを設定する <a class="header-anchor" href="#アカウントアイコンを設定する" aria-label="Permalink to &quot;アカウントアイコンを設定する&quot;">​</a></h3><p>デフォルトのアイコン利用は避け、アカウント登録時に各自のアイコン画像を登録する。</p><p>理由:</p><ul><li>チャットコミュニケーションにおいて、アイコン画像は個人識別に有用なため</li></ul><p>また、GitHub/GitLab、Google Workspace、その他利用サービスも同様のアイコンを利用することで、個人を識別しやすくなる。</p><h3 id="検索性の高い氏名-full-name-を設定する" tabindex="-1">検索性の高い氏名（Full name）を設定する <a class="header-anchor" href="#検索性の高い氏名-full-name-を設定する" aria-label="Permalink to &quot;検索性の高い氏名（Full name）を設定する&quot;">​</a></h3><p>表示名（Display name） もしくは氏名（Full name） にて、ローマ字及び漢字（無ければカタカナ）でのフルネームを登録すること。表示名はチームごとに書き方の異なるケースが多いので、本ガイドラインでは氏名に記載することを推奨する。例えば「未来 太郎」の場合、「Taro Mirai (未来 太郎)」という記載を推奨する。</p><p>理由:</p><ul><li>Slackではアカウント名のインクリメンタルサーチが強力であり、ローマ字と漢字のどちらでもサジェストされる状態にすることでユーザビリティの向上が期待できるため</li></ul><h3 id="ユーザーグループの推奨" tabindex="-1">ユーザーグループの推奨 <a class="header-anchor" href="#ユーザーグループの推奨" aria-label="Permalink to &quot;ユーザーグループの推奨&quot;">​</a></h3><p>ユーザーグループの利用を推奨する。ただし、ゲストユーザーは追加できない。該当するメンバーがチャンネルに在籍する場合は、その旨をメンバー全員が理解し、コミュニケーションから除外してしまわないように注意すること。</p><div class="tip custom-block"><p class="custom-block-title">ユーザーグループを作成できない状態の回避策</p><p>ユーザーグループを作成できない状態（メンバーがワークスペース間にまたがっている場合等）でも、メンション先の対象者全員が個別に自分のSlack設定&gt;Notification&gt;My Keywordsに「＠〇〇チーム」と予約語を登録することで、擬似的にグループメンションが可能である</p></div><h2 id="チャンネル命名規則" tabindex="-1">チャンネル命名規則 <a class="header-anchor" href="#チャンネル命名規則" aria-label="Permalink to &quot;チャンネル命名規則&quot;">​</a></h2><h3 id="外部組織メンバーが在籍するチャンネルの命名" tabindex="-1">外部組織メンバーが在籍するチャンネルの命名 <a class="header-anchor" href="#外部組織メンバーが在籍するチャンネルの命名" aria-label="Permalink to &quot;外部組織メンバーが在籍するチャンネルの命名&quot;">​</a></h3><p>Slack コネクト等でチャンネル内に社外のメンバーが含まれる場合には、チャンネル名の先頭に <code>---ext</code> をつける。</p><p>理由:</p><ul><li>全社的に統一されたプレフィックスにより、内部の進行について相談する発言を、取引先メンバーが在籍するチャンネルに誤投稿してしまうような、外部コミュニケーションのミスを防ぐため</li><li>チャンネルはセクションという単位でグルーピング可能となり、用途や組織を表現するプレフィックスで並び順を制御する必然性が薄れたため</li></ul><h2 id="投稿内容ポリシー" tabindex="-1">投稿内容ポリシー <a class="header-anchor" href="#投稿内容ポリシー" aria-label="Permalink to &quot;投稿内容ポリシー&quot;">​</a></h2><h3 id="敬称は不要" tabindex="-1">敬称は不要 <a class="header-anchor" href="#敬称は不要" aria-label="Permalink to &quot;敬称は不要&quot;">​</a></h3><p>敬称は省略して、 <code>@mano メッセージ内容</code> といった形式でコメントすること。どうしても敬称を付けて欲しい場合、表示名をさん付けにするハックも存在するため、受信者側で調整する。</p><p>理由:</p><ul><li>コミュニケーションを迅速・シンプルにするため</li></ul><h3 id="絵文字や感嘆符を活用する" tabindex="-1">絵文字や感嘆符を活用する <a class="header-anchor" href="#絵文字や感嘆符を活用する" aria-label="Permalink to &quot;絵文字や感嘆符を活用する&quot;">​</a></h3><p>積極的に活用することを推奨する。テキストコミュニケーションは、画像や音声が伝わらない分、冷たく捉えられがちである。特にリーダーなど上位のポジションにいる場合は、メンバーから威圧的に捉えられないよう配慮するのが好ましい。</p><p>「では、Aの方針でよろしくお願いします！」「では、Aの方針でよろしくお願いします:ganbatte:」 など付けることで、不機嫌でないことがわかり、心理的安全性が保たれる。</p><p>カスタム絵文字の追加も推奨する。チーム内でしか通用しない（例えば内輪ネタのような）カスタム絵文字であっても気軽に追加して良い。</p><p>理由:</p><ul><li>より良いコミュニケーション手段を模索すること自体が、コミュニケーションを活性化させ、価値を向上させるため <ul><li>なお、他人の名誉を毀損するなど、社会人／プロフェッショナルとしてふさわしくない内容は登録しないこと</li></ul></li></ul><h3 id="日付は絶対表記を用いる" tabindex="-1">日付は絶対表記を用いる <a class="header-anchor" href="#日付は絶対表記を用いる" aria-label="Permalink to &quot;日付は絶対表記を用いる&quot;">​</a></h3><p>Slackに閉じた話ではないが、「明日」や「来週」といった表記は、数日後に読むと期日の認識がズレてしまう可能性がある。そのため、2025.1.29 など絶対表記を用いる。</p><h3 id="絵文字リアクションによる積極応答" tabindex="-1">絵文字リアクションによる積極応答 <a class="header-anchor" href="#絵文字リアクションによる積極応答" aria-label="Permalink to &quot;絵文字リアクションによる積極応答&quot;">​</a></h3><p>非同期のコミュニケーションでは、発信者は「投稿内容を見てくれたのかどうか」が気になる。特に確認依頼は見ていればOKで、回答を急がないケースは想像以上に多い。<br> こういった場面は、::後で確認します:: といった絵文字リアクションで解決するため、積極的に活用する。</p><p>また、参加者が多いチャンネルでの発信は勇気がいる。コミュニケーションを活性化させるためにも、絵文字リアクションを積極的に行い推奨／礼賛することが望ましい。</p><div class="warning custom-block"><p class="custom-block-title">「〇〇してほしい」 「〇〇について教えてほしい」（相談セクション）への対応は絵文字リアクションだけで済まさない</p><p>「投稿内容を見てくれたのか」ではなく、「投稿内容を理解して次のアクションをとってくれるのか」を知りたい場面も多い。 そのような場面では、絵文字リアクションのみで済まさず、対応可否をコメントでフィードバックする必要がある。</p></div><h3 id="dmはなるべく避ける" tabindex="-1">DMはなるべく避ける <a class="header-anchor" href="#dmはなるべく避ける" aria-label="Permalink to &quot;DMはなるべく避ける&quot;">​</a></h3><p>基本的には、DMよりチャンネルでのやり取りを推奨する。チャンネルの中でも、より参加人数が多い（よりオープンな）ものを推奨する。</p><p>理由:</p><ul><li>重複した質問を防ぐため</li><li>質問事項がチーム／組織に共有されることで、全体の効率が上がるため</li><li>後から類似の困りごとを持ったメンバーが、キーワード検索で見つけやすくするため</li></ul><div class="tip custom-block"><p class="custom-block-title">DMの利用を推奨するケース</p><ul><li>人事相談、機密事項を含む場合（ <a href="#機密情報の流出に注意する">機密情報の流出に注意する</a> 章を参照）</li><li>限られたメンバーのみに、ファイル共有をしたい場合</li><li>後から検索させる意味がないやり取り（ 「最近元気？」 と同期に投げる場合など）</li></ul></div><h3 id="timesの推奨" tabindex="-1">timesの推奨 <a class="header-anchor" href="#timesの推奨" aria-label="Permalink to &quot;timesの推奨&quot;">​</a></h3><p>timesとは、分報や作業スレッドとも呼ばれ、今取り組んでいることや困っていることを投稿することを指す。</p><p>推奨は次のとおり。</p><ul><li>timesの利用を推奨する</li><li>メンバーごとのtimesチャンネルではなく、スレッドでの利用を推奨する</li><li>timesスレッドを他のメンバーが参照するかは任意で良い</li></ul><p>理由:</p><ul><li>スレッド単位であれば、本チャンネル側のノイズになることはない。参加メンバーが多い場合は、times専用のチャンネルを作成すれば良い</li><li>メンバーごとの times チャンネルは、チャンネルが必要以上に増えるので推奨しない</li><li>必要に応じて、作業状況を本人に確認（ポーリング）しなくても把握できる</li><li>ハマったことや調べたことが、後々キーワード検索で見つかり、新規参画者の助けになることも多い</li></ul><div class="warning custom-block"><p class="custom-block-title">timesスレッドの注意</p><p>times内とはいえ、他の人が不快になるような発言や不適切な利用は避ける（チームメンバーが閲覧可能であることを忘れない）。</p></div><div class="tip custom-block"><p class="custom-block-title">timesスレッドでのやり取りにこだわりすぎない</p><ul><li>timesスレッドのコメント数は100以上になることもある。その途中で他メンバーに相談事などでメンションを飛ばすと、呼ばれたメンバーには「該当のスレッドの全コメントをチェックしたほうが良いのか」といった迷いが生じる。そのため、相談はtimes内ではなく別メッセージに切り出して行うことを推奨する</li><li>なお、timesの投稿を読んで欲しいときは、timesスレッドでメンションしても良い</li><li>timesのメンションを受けたユーザーが、その後の投稿の通知を受け取りたくない場合は、そのスレッドの通知を切ることで対応する</li></ul></div><div class="tip custom-block"><p class="custom-block-title">スレッドのフォローは適当なタイミングで外す（外してもらう）</p><p>timesスレッドでメンションされると、その後にもスレッド内の投稿がメンション先のユーザーに通知が飛び続けてしまうのではないか？ という懸念がある。</p><ul><li>必要に応じて該当スレッドのフォローを外せば良いので、上記観点でメンションを行う／行わないの判断は行わなくても良い</li><li>前述のとおり、timesのコメントを（全て）読んで欲しいか否かでスレッド内でメンションするかどうかを決める</li></ul></div><h3 id="メッセージ-スレッドのトップ-は具体的に書く" tabindex="-1">メッセージ（スレッドのトップ）は具体的に書く <a class="header-anchor" href="#メッセージ-スレッドのトップ-は具体的に書く" aria-label="Permalink to &quot;メッセージ（スレッドのトップ）は具体的に書く&quot;">​</a></h3><p>チャンネルのメッセージ（スレッド先頭の投稿）では、話題を端的に表現する。ただし、返信スレッドの中を確認しないと内容が分からないようなメッセージ（タイトル）は非推奨とする。</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">メッセージ（スレッド先頭の投稿）</th></tr></thead><tbody><tr><td style="text-align:left;">✅推奨例</td><td style="text-align:left;">@mirai チケット #4191 foo bar failed のビルドエラーの解消についての相談です。スタックトレースはスレッド内に記載します</td></tr><tr><td style="text-align:left;">❌非推奨例</td><td style="text-align:left;">レビュー依頼</td></tr></tbody></table><p>なお、メンションはメッセージ（スレッド先頭）に付けるか、返信スレッド内に付けるかは任意とする。</p><div class="info custom-block"><p class="custom-block-title">参考</p><ul><li><a href="https://techblog.cartaholdings.co.jp/entry/better_slack_communication" target="_blank" rel="noreferrer">Slackで要件を書かずに「質問があります。詳細はスレッドに記載」をやめたほうがいい理由 - CARTA TECH BLOG</a></li><li><a href="https://www.m3tech.blog/entry/2024/12/07/110000" target="_blank" rel="noreferrer">リモートワーク時代を生き抜くAI・機械学習チームの働き方 - エムスリーテックブログ</a></li></ul></div><h3 id="メッセージのurlを活用する" tabindex="-1">メッセージのURLを活用する <a class="header-anchor" href="#メッセージのurlを活用する" aria-label="Permalink to &quot;メッセージのURLを活用する&quot;">​</a></h3><p>Slackは本来、フロー情報向けのツールである。しかしこれをWikiなどのストック情報向けツールに転記する労力は高く、運用が形骸化しがちである。そのため、例えば設計方針について議論したスレッドのURLを作業チケットやWikiなどに記載し、トレース可能にする運用を取るチームも良く聞く。本ガイドラインもスレッドURLの活用を推奨する。</p><p>なお、決定事項の経緯や議論内容を数年後に確認することもしばしば発生する。そのため議論があればスレッドを利用し、かつ同一スレッドで複数のテーマを混ぜないことが望ましい。関連議論がいくつかのスレッドに分かれる場合、相互に関連スレッドのURLを投稿しておくと良い。</p><div class="tip custom-block"><p class="custom-block-title">Slackにおける情報ストック機能</p><p>Canvas、ブックマーク、ピン留め機能を活用することで、Slack内にてストック情報を取り扱うことも可能である。ユースケースに合わせて使い分ける。</p><ul><li><strong>ブックマーク</strong>: PJで利用している課題管理サービスのURLなどを共有したい場合</li><li><strong>ピン留め</strong>: PJメンバーに都度参照して欲しい特定のメッセージがある場合</li><li><strong>Canvas</strong>: 情報量が多く章立てて整理をしたい場合</li></ul></div><h3 id="also-send-to-channelは乱発しない" tabindex="-1">Also send to channelは乱発しない <a class="header-anchor" href="#also-send-to-channelは乱発しない" aria-label="Permalink to &quot;Also send to channelは乱発しない&quot;">​</a></h3><p>Also send to channel を利用することで、スレッド内の投稿をチャンネルのタイムライン側に重複投稿できる。</p><p>推奨は次のとおり。</p><ul><li>過去のスレッドでやり取りを再開した場合に、チャンネルに在籍するメンバーへ通知する目的で用いる</li><li>スレッド内で重要な決定事項に至った場合は、メンバーに周知する目的で用いる</li><li>スレッド内のやり取りを細かくAlso send to channelすると、スレッドを用いる意味が薄れるので、利用頻度は抑えるように意識する</li></ul><h3 id="canvasの利用について" tabindex="-1">Canvasの利用について <a class="header-anchor" href="#canvasの利用について" aria-label="Permalink to &quot;Canvasの利用について&quot;">​</a></h3><p>Canvasは、Slack内で情報を作成、整理、共有するための機能である。</p><p>推奨は次の通り。</p><ul><li>新規参画者向け情報をCanvasに集約する <ul><li>オンボーディングガイドライン: プロジェクト概要、チームメンバー紹介、主要なチャンネルリスト、開発環境へのリンク集など</li><li>プロジェクト固有のルールや文化: コミュニケーションルール、定例会議の情報、勤怠連絡フロー、チャージコードなど</li></ul></li><li>繰り返し利用する手順や手続きはCanvasに集約する <ul><li>各種アカウントの申請方法やセットアップ方法など</li></ul></li></ul><p>理由:</p><ul><li>新規参画者は、まずCanvasを見れば必要な情報にアクセスできる状態を目指すことで、オンボーディングコストを減らすため</li><li>チャンネルのログに埋もれず、必要な時に誰でも手順を確認できるようにするため</li><li>情報は常に最新に保つ必要があるため、複数メンバーで編集できるCanvasが適している</li></ul><div class="tip custom-block"><p class="custom-block-title">ピン留めとの使い分けについて</p><p>ピン留めされた投稿は、投稿者しか編集ができない。そのため後から追記や修正が必要になりそうな情報は、<strong>最初からCanvasに記載する</strong>ことを強く推奨する。これにより、チャンネルに所属するメンバー全員で編集が可能となり、記載内容の変更依頼などの余計なやり取りを減らすこともできる。</p></div><h3 id="広めの通知に注意する" tabindex="-1">広めの通知に注意する <a class="header-anchor" href="#広めの通知に注意する" aria-label="Permalink to &quot;広めの通知に注意する&quot;">​</a></h3><h4 id="channel" tabindex="-1"><code>@channel</code> <a class="header-anchor" href="#channel" aria-label="Permalink to &quot;`@channel`&quot;">​</a></h4><p>緊急時を除き、原則利用を禁止する。</p><p>理由:</p><ul><li><code>@channel</code> はSlackを見ていないユーザーにも通知が飛び、休暇中のメンバー等にも影響があるため</li><li>受取側で制御すべきという考えもあるが、システム障害対応など優先度の高い問い合わせのために、あえて通知をOFFにしていないメンバーも存在するため</li></ul><div class="tip custom-block"><p class="custom-block-title">@channel を利用して良い場合</p><p>システム障害時など、重大かつ緊急度が高い場合は <code>@channel</code> を使っても良い。</p></div><h4 id="here" tabindex="-1"><code>@here</code> <a class="header-anchor" href="#here" aria-label="Permalink to &quot;`@here`&quot;">​</a></h4><p>メールのCCに似た意図で <code>@here</code> を使うことは禁止とする。</p><p>✅️推奨ケース</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@真野 @村田 ○○の件ですが\\~</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>❌️NG（メールのCC的な形で <code>@here</code> を追加）</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@真野 @村田 @here ○○の件ですが</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>理由:</p><ul><li>メールのCC的な参考情報であれば、<code>@here</code> を付けずに、チャンネルの未読通知で後で見ることができるため</li><li>真に必要ではないときの通知が常態化すると、<code>@here</code> の緊急性やアクションを求める意味合いが弱まり、真に必要なときに読み飛ばされてしまう可能性が上がるため（「狼少年」現象）</li></ul><div class="tip custom-block"><p class="custom-block-title">@hereを利用して良い場合</p><ul><li>全員にアクションを促す連絡事項を行う場合 <ul><li>例: 「@here {チーム全体イベント} への出欠可否の回答を絵文字リアクションでお願いします」</li><li>例: 「@here 12/10までに評価入力を、忘れず対応をお願いします」</li><li>例: 「@here 経費精算は月末までなので、みなさん忘れずに対応をお願いします」</li></ul></li></ul></div><h3 id="メンション範囲は適切に" tabindex="-1">メンション範囲は適切に <a class="header-anchor" href="#メンション範囲は適切に" aria-label="Permalink to &quot;メンション範囲は適切に&quot;">​</a></h3><h4 id="過剰なメンションの抑制" tabindex="-1">過剰なメンションの抑制 <a class="header-anchor" href="#過剰なメンションの抑制" aria-label="Permalink to &quot;過剰なメンションの抑制&quot;">​</a></h4><p>原則、レビュー依頼や確認依頼など、行動してほしい時にメンションを付けるものとする。「@mirai ありがとうございます！」 「@mirai 承知しました！」等の挨拶にメンションを付けると、通知が来てノイズになるため非推奨とする。メンションを付けず <code>ありがとうございます！</code> とすると良い。</p><div class="tip custom-block"><p class="custom-block-title">情報提供依頼系など善意やり取りはきちんとフィードバックする</p><p>情報提供依頼はSlackと親和性が良いタスクである。依頼者は、回答してもらった人に 👍 絵文字だけのリアクションを取る場合があるが、フィードバック付きでコメントを返すことが望ましい。情報提供者としても、その情報が役立ったのかどうかへの関心は強いためである。<br> フィードバックが難しい場合や、スレッド投稿数をなるべく減らしたい場合は、複数のリアクションを返し感謝の意を強調すると良い。 👍️🎉☺[神] のようなイメージである。</p></div><h4 id="メンションの宛先をできる限り絞り込む" tabindex="-1">メンションの宛先をできる限り絞り込む <a class="header-anchor" href="#メンションの宛先をできる限り絞り込む" aria-label="Permalink to &quot;メンションの宛先をできる限り絞り込む&quot;">​</a></h4><p>単なる周知目的ではなく行動を促したい相手に絞ること。お見合いになってボールが浮いてしまう可能性がある。「@mirai @mano @murata @ozawa @tanimura AWSの設定で確認したいのですが～」などと広すぎる場合、宛先メンバーは自分よりもっと詳しい人がいるかも知れないと、回答すべきかどうか逡巡してしまう。できれば1、2名に宛先を絞り、宛先メンバーから別の有識者メンバーにディスパッチしてもらう運用を考えると良い。</p><h3 id="予約投稿を活用する" tabindex="-1">予約投稿を活用する <a class="header-anchor" href="#予約投稿を活用する" aria-label="Permalink to &quot;予約投稿を活用する&quot;">​</a></h3><p>特にリーダーからメンバーに対して、深夜（22:00-6:00など）や休日など業務時間外の投稿は原則禁止とし、予約投稿を推奨する。</p><p>理由:</p><ul><li>仕事とプライベートにメリハリを持たせることで、成果の向上を期待できるため</li><li>（システム障害等）緊急時の依頼と混同してしまうため。次回出勤時の対応で良いものと区別すること</li><li>Slackのアップデートにより、チャンネル投稿に閉じず<a href="https://x.com/SlackHQ/status/1816461445585916409" target="_blank" rel="noreferrer">スレッドへの予約投稿が可能となった</a></li></ul><div class="tip custom-block"><p class="custom-block-title">受け取り側で制御する方針</p><p>「緊急時は電話連絡とし、メンションへの即対応を求めない」と取り決めるのであれば、受け取り側で通知時間を設定し、送る側は送信時間に気を遣わない運用も可とする。ただし、時間外の通知を翌営業日に対応しようと考えて忘れてしまう場合がある。受け取り側は、通知を受けた時点でリマインダーを仕込む、アクティビティ &gt; @メンション を定期的に確認する、といった工夫をする。</p></div><h3 id="不在の表明" tabindex="-1">不在の表明 <a class="header-anchor" href="#不在の表明" aria-label="Permalink to &quot;不在の表明&quot;">​</a></h3><p>表示名に不在情報を記載（例：<code>@sato_11/8休</code>）しておくことを推奨する。受信側は不在時の緊急性の低い通知を防げ、送信側は即レスを期待せずに済む。不在情報がGoogleカレンダーなど別のスケジュールアプリで管理されていたとしても、Slackでの依頼時に気付けるため。</p><div class="tip custom-block"><p class="custom-block-title">ステータス機能で「休暇中🏝️」にすればよいのではないか</p><p>ステータス機能でもチームメンバーに不在であるという状態を表明できる。しかし、次の観点で表示名での表明を推奨する。</p><ul><li>いつから、いつまで休暇なのかステータスでは不明である <ul><li>期間が分かれば、予約投稿で休暇明けに投稿するなどのアクションがすぐ取れる</li></ul></li><li>休暇だけでなく出張中などの情報も提示できる <ul><li>例えば、海外出張なので時差があると分かれば、チームメンバーにどれくらいでレスポンスが来そうか予想ができるようになる</li></ul></li><li>ステータス変更に気が付きにくい <ul><li>メンションを付けて投稿する時に常時表示されるわけではないので、ステータスは見過ごされる可能性が高い</li></ul></li></ul></div><div class="warning custom-block"><p class="custom-block-title">復帰時に元に戻すことを忘れない</p><p>復帰時に表示名を元に戻すことを忘れがちであるため、注意すること。</p></div><h3 id="可読性を上げるための書式設定" tabindex="-1">可読性を上げるための書式設定 <a class="header-anchor" href="#可読性を上げるための書式設定" aria-label="Permalink to &quot;可読性を上げるための書式設定&quot;">​</a></h3><p>箇条書き、太字、引用などの装飾は、積極的に活用する。文章を構造化することで、読み手にとっての負荷が軽減されるため。Slackの書式以外にも、【すみかっこ】等の記号でセクションを表現することも推奨する。</p><h3 id="エラーメッセージの画像添付非推奨、テキストスニペットの推奨" tabindex="-1">エラーメッセージの画像添付非推奨、テキストスニペットの推奨 <a class="header-anchor" href="#エラーメッセージの画像添付非推奨、テキストスニペットの推奨" aria-label="Permalink to &quot;エラーメッセージの画像添付非推奨、テキストスニペットの推奨&quot;">​</a></h3><p>有識者にスタックトレースなどのエラー内容を画像添付して問い合わせることは原則として非推奨とし、テキストで共有することを推奨する。また、共有内容が長文の場合にはテキストスニペット使用が好ましい。</p><p>理由:</p><ul><li>相談相手も裏取りとしてスタックトレースの内容を検索することが多々あるため</li><li>後から同様の困り事を持った人が、キーワード検索で見つけにくくなるため</li><li>長いログをそのまま貼り付けるとスレッドを広く埋め尽くしてしまうが、テキストスニペットを使えば1投稿あたりのデフォルト表示域を制限できる</li></ul><div class="tip custom-block"><p class="custom-block-title">スクリーンショットなどの画像で共有しても良い場合</p><ul><li>コピーできないエラー表示など、テキストでの情報提供が難しい場合</li><li>（相談相手が、コピー範囲などを独自判断で狭められることを防ぐなどの理由で）スクリーンショットでの共有を希望する場合</li></ul></div><div class="tip custom-block"><p class="custom-block-title">テキストスニペット利用時は、タイトル（ファイル名）に拡張子をつける</p><p>Slackはテキストスニペットに設定されたタイトルをそのままファイル名としてダウンロードするよう動作する。この際拡張子が設定されていないとSlack内でそのままファイルを開くことができなくなってしまう。</p></div><h3 id="機密情報の流出に注意する" tabindex="-1">機密情報の流出に注意する <a class="header-anchor" href="#機密情報の流出に注意する" aria-label="Permalink to &quot;機密情報の流出に注意する&quot;">​</a></h3><p>営業情報、個人情報、人事情報など機密情報は、「最小権限の原則」に従い、なるべく宛先を狭めるべきである。センシティブな内容をやり取りする場合は、参加者を絞ったプライベートチャンネル／DMグループの活用を推奨する。</p><div class="tip custom-block"><p class="custom-block-title">メッセージ通知にも気をつける</p><p>画面投影やWebミーティングでの画面共有時、意図しないメッセージ通知が見えてしまう事がある。Slackの通知設定にて次に示す設定を施すことで防ぐことが可能なので活用すると良い。</p><ul><li>通知自体をOFFにする</li><li>通知はOFFにしないが、メッセージ内容は非表示にする</li></ul></div><h3 id="ファイルの共有に注意する" tabindex="-1">ファイルの共有に注意する <a class="header-anchor" href="#ファイルの共有に注意する" aria-label="Permalink to &quot;ファイルの共有に注意する&quot;">​</a></h3><p>Slackのファイル共有は便利であるが、ファイルのオーナー（作成者）とチャンネルにメンバー追加できる担当者が必ずしも1:1ではない。そのため、推奨は次のとおり。</p><ul><li>Google Driveなどにファイルをアップロードする</li><li>Google Drive側で適切な権限に絞り込む</li></ul><p>理由:</p><ul><li>Google Drive側で権限設定が可能</li><li>Slack上にアップロードされたファイルが、別のチャンネルに再アップロードされて収集がつかなくなるといったケースを防ぎ、統制を図るため</li></ul><div class="tip custom-block"><p class="custom-block-title">ファイルを直接アップロードしても良い場合</p><p>社外勉強会の登壇資料など、一般に「公開済み／公開予定 」のファイルはアップロードして良い。</p></div><div class="tip custom-block"><p class="custom-block-title">Google Driveのアップロードしたpptxファイルの予期せぬ更新を防ぐ</p><p>Google Driveにアップロードしたpptxファイルのリンクを共有すると、Google Slideで開かれてしまい、スタイルが崩れて保存されてしまうという事象が後を絶たない。回避策として直接Slack上にpptxファイルをアップロードする流派もあるが、チャンネルの参加人数が多い場合は採用しにくい。</p><p>以下のように、URLを <code>view</code>(あるいは <code>preview</code>) と書き換えることで不用意な更新を防ぐことができる。Slack上のプレビュー表示も問題なく、目立ったデメリットが無いため、<code>view</code> にしたURLを共有することを推奨する。</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://docs.google.com/document/d/FILE_ID/edit</span></span>\n<span class="line"><span>↓</span></span>\n<span class="line"><span>https://docs.google.com/document/d/FILE_ID/view</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>URLは以下の手順Aまたは手順Bのどちらかの画面操作からも取得可能である。</p><ul><li>手順A <ol><li>Google Drive上で3点リーダー</li><li>アプリ＞新しいタブで開く、URLをコピー</li></ol></li><li>手順B <ol><li>Google Drive上で3点リーダー</li><li>アプリ＞プレビューで開く</li><li>プレビュー画面の右上の三点リーダーをクリックし、「新しいウィンドウで開く」を選択し、URLをコピー</li></ol></li></ul><p><code>view</code> と <code>preview</code> に大きな違いはない。<code>view</code> の方がファイルのメタ情報などが表示され、 <code>preview</code> はより表示領域が広くコンテンツに集中して確認できる点が異なる。<code>preview</code> から <code>view</code> への画面遷移は可能だが、<code>view</code> から <code>preview</code> への導線は無い。</p><div class="info custom-block"><p class="custom-block-title">参考</p><p><a href="#2.3.-テンプレート共有を目的としたプレビューモード">Googleドライブ・ドキュメントのURL操作Tips</a></p></div></div><div class="tip custom-block"><p class="custom-block-title">Google DriveのURL共有時プレビュー表示のよるリスクについて</p><p>表紙がプレビューされるが、次の理由により問題ないという立場を取る。</p><ul><li>プレビュー表示されるのは1枚目（1シート目）であり、通常は表紙ページが見られるのみ</li><li>ファイルが存在すること自体は知られて良い（チャンネルに投稿しているため）と考えられる</li><li>なにか問題があれば、プレビューを表示しない操作がSlack上で可能なため</li></ul></div><h3 id="プレビューの表示数は抑える" tabindex="-1">プレビューの表示数は抑える <a class="header-anchor" href="#プレビューの表示数は抑える" aria-label="Permalink to &quot;プレビューの表示数は抑える&quot;">​</a></h3><p>Slackのリンク共有はプレビューが自動的に付与され、リンク先の情報が一目でわかり利便性が高い。しかし、複数のプレビューが表示されると投稿した本文側の注目度が下がり、またチャンネル全体の視認性も低下してしまう。</p><p>そのため、1ポストにつき1プレビュー程度になるよう送信者側で整理する運用が望ましい。リンクが重要でない場合はプレビュー表示そのものを削除した方が、読み手が投稿内容に集中できる。</p><p>なお、ニュースやブログ記事などのURLそのものを共有することが主目的であれば、1投稿で複数のプレビューを表示させたほうが良い場面もある。読み手に集中して欲しいコンテンツが何かによって適切に使い分ける。</p><h3 id="プライベートチャンネルの投稿に対する引用" tabindex="-1">プライベートチャンネルの投稿に対する引用 <a class="header-anchor" href="#プライベートチャンネルの投稿に対する引用" aria-label="Permalink to &quot;プライベートチャンネルの投稿に対する引用&quot;">​</a></h3><p>プライベートチャンネルの投稿コメントを、別のチャンネルにURL引用で投稿すると、該当チャンネルの権限を有していないユーザーにも参照権限を与えてしまう。引用時にはセンシティブな内容が含まれていないか確認するよう注意する。</p>',138))])}const v=e(r,[["render",p]]);export{k as __pageData,v as default};
